PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY, organization_id TEXT REFERENCES organizations(id), name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('OWNER','VIEW_ONLY','STORE_MANAGER','ADMIN')), active INTEGER NOT NULL DEFAULT 1, sms_enabled INTEGER NOT NULL DEFAULT 0, timezone TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, recipient_kind TEXT NOT NULL DEFAULT 'STANDARD' CHECK(recipient_kind IN ('STANDARD','PILOT_ADMIN')), complaint_notifications_enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE stores (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), dunkin_store_number TEXT NOT NULL UNIQUE, name TEXT NOT NULL, address TEXT NOT NULL, city TEXT NOT NULL, state TEXT NOT NULL, postal_code TEXT NOT NULL, phone TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, manager_id TEXT REFERENCES users(id), backup_manager_id TEXT REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE complaints (id TEXT PRIMARY KEY, external_case_id TEXT NOT NULL UNIQUE, store_id TEXT REFERENCES stores(id), assigned_manager_id TEXT REFERENCES users(id), subject TEXT NOT NULL, complaint_text TEXT NOT NULL, category TEXT NOT NULL, severity TEXT NOT NULL, status TEXT NOT NULL, is_ack_overdue INTEGER NOT NULL DEFAULT 0, is_resolution_overdue INTEGER NOT NULL DEFAULT 0, routing_reason TEXT NOT NULL, routing_confidence TEXT NOT NULL, received_at TEXT NOT NULL, dunkin_acknowledged_at TEXT, acknowledgment_body TEXT, manager_notified_at TEXT, manager_acknowledged_at TEXT, investigation_started_at TEXT, resolution_submitted_at TEXT, closed_at TEXT, closed_by TEXT, ack_deadline TEXT NOT NULL, resolution_deadline TEXT, manager_findings TEXT, customer_contacted INTEGER, customer_contact_outcome TEXT, corrective_action TEXT, resolution_notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, follow_ups TEXT NOT NULL DEFAULT '[]', source TEXT NOT NULL DEFAULT 'MANUAL', gmail_message_id TEXT, gmail_thread_id TEXT, source_sender TEXT, customer_name TEXT, customer_email TEXT, customer_phone TEXT, occurrence_at TEXT, customer_contacted_at TEXT, acknowledgement_status TEXT NOT NULL DEFAULT 'DISABLED', owner_reviewed_at TEXT, reopened_at TEXT, reopen_reason TEXT, owner_notes TEXT, ingestion_mode TEXT NOT NULL DEFAULT 'LIVE'
  CHECK(ingestion_mode IN ('LIVE','BACKFILL','TEST')), operational_started_at TEXT);
CREATE TABLE complaint_events (id TEXT PRIMARY KEY, complaint_id TEXT NOT NULL REFERENCES complaints(id), event_type TEXT NOT NULL, actor TEXT NOT NULL, timestamp TEXT NOT NULL, metadata TEXT);
CREATE TABLE notifications (id TEXT PRIMARY KEY, complaint_id TEXT REFERENCES complaints(id), event_type TEXT NOT NULL, recipient_user_id TEXT NOT NULL REFERENCES users(id), channel TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL, provider TEXT NOT NULL, provider_message_id TEXT, created_at TEXT NOT NULL, sent_at TEXT, delivered_at TEXT, failed_at TEXT, failure_reason TEXT);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE notification_callbacks (id TEXT PRIMARY KEY, provider_message_id TEXT NOT NULL, status TEXT NOT NULL, received_at TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE test_notification_rate_limits (recipient_user_id TEXT PRIMARY KEY REFERENCES users(id), last_sent_at TEXT NOT NULL);
CREATE TABLE store_aliases (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  alias_normalized TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL
);
CREATE TABLE user_store_assignments (
  user_id TEXT NOT NULL REFERENCES users(id),
  store_id TEXT NOT NULL REFERENCES stores(id),
  created_at TEXT NOT NULL,
  PRIMARY KEY(user_id, store_id)
);
CREATE TABLE gmail_messages (
  gmail_message_id TEXT PRIMARY KEY,
  gmail_thread_id TEXT NOT NULL,
  complaint_id TEXT REFERENCES complaints(id),
  internal_date TEXT NOT NULL,
  sender TEXT NOT NULL,
  recipients TEXT NOT NULL,
  subject TEXT NOT NULL,
  message_id_header TEXT,
  in_reply_to TEXT,
  references_header TEXT,
  processing_status TEXT NOT NULL,
  processing_detail TEXT,
  is_follow_up INTEGER NOT NULL DEFAULT 0,
  acknowledgment_status TEXT NOT NULL DEFAULT 'NOT_APPLICABLE',
  first_seen_at TEXT NOT NULL,
  processed_at TEXT,
  updated_at TEXT NOT NULL
);
CREATE TABLE email_acknowledgments (
  id TEXT PRIMARY KEY,
  complaint_id TEXT NOT NULL UNIQUE REFERENCES complaints(id),
  gmail_thread_id TEXT NOT NULL,
  source_gmail_message_id TEXT NOT NULL,
  idempotency_key TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL,
  provider_message_id TEXT,
  attempt_count INTEGER NOT NULL DEFAULT 0,
  last_error_code TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  sent_at TEXT
);
CREATE TABLE integration_events (
  id TEXT PRIMARY KEY,
  integration TEXT NOT NULL,
  event_type TEXT NOT NULL,
  entity_id TEXT,
  outcome TEXT NOT NULL,
  detail_code TEXT,
  metadata TEXT,
  created_at TEXT NOT NULL
);
CREATE TABLE background_job_runs (
  id TEXT PRIMARY KEY,
  job_name TEXT NOT NULL,
  started_at TEXT NOT NULL,
  completed_at TEXT,
  outcome TEXT NOT NULL,
  processed_count INTEGER NOT NULL DEFAULT 0,
  error_code TEXT
);
CREATE TABLE background_job_locks (
  job_name TEXT PRIMARY KEY,
  locked_until TEXT NOT NULL,
  owner_run_id TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE signalwire_reconciliations (
  id TEXT PRIMARY KEY,
  notification_id TEXT NOT NULL REFERENCES notifications(id),
  provider_message_id TEXT NOT NULL,
  previous_status TEXT NOT NULL,
  authoritative_status TEXT NOT NULL,
  outcome TEXT NOT NULL,
  reconciled_at TEXT NOT NULL
);
CREATE TABLE escalation_events (
  id TEXT PRIMARY KEY,
  complaint_id TEXT NOT NULL REFERENCES complaints(id),
  escalation_type TEXT NOT NULL,
  escalation_sequence INTEGER NOT NULL,
  created_at TEXT NOT NULL,
  UNIQUE(complaint_id, escalation_type, escalation_sequence)
);
CREATE TABLE mail_source_messages (
  id TEXT PRIMARY KEY,
  provider TEXT NOT NULL CHECK(provider IN ('MICROSOFT_GRAPH','GMAIL')),
  mailbox_key TEXT NOT NULL,
  provider_message_id TEXT NOT NULL,
  internet_message_id TEXT,
  conversation_id TEXT,
  parent_folder_id TEXT,
  direction TEXT NOT NULL CHECK(direction IN ('INBOUND','OUTBOUND','UNKNOWN')),
  received_at TEXT NOT NULL,
  discovered_at TEXT NOT NULL,
  subject TEXT NOT NULL,
  sender_address TEXT NOT NULL,
  recipients_json TEXT NOT NULL DEFAULT '[]',
  raw_content_ref TEXT,
  raw_content_sha256 TEXT,
  transport_metadata_sha256 TEXT,
  ingestion_mode TEXT NOT NULL CHECK(ingestion_mode IN ('LIVE','BACKFILL','TEST')),
  processing_state TEXT NOT NULL CHECK(processing_state IN (
    'DISCOVERED','PROCESSING','RETRY_WAIT','REVIEW_REQUIRED','NON_ACTIONABLE','COMPLETED','FAILED_PERMANENT'
  )),
  lease_owner TEXT,
  lease_expires_at TEXT,
  attempt_count INTEGER NOT NULL DEFAULT 0,
  last_error_code TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(provider,mailbox_key,provider_message_id)
);
CREATE TABLE mail_discovery_cursors (
  id TEXT PRIMARY KEY,
  provider TEXT NOT NULL,
  mailbox_key TEXT NOT NULL,
  scope TEXT NOT NULL,
  cursor_value TEXT,
  high_water_received_at TEXT,
  last_started_at TEXT,
  last_succeeded_at TEXT,
  last_error_code TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(provider,mailbox_key,scope)
);
CREATE TABLE mail_processing_runs (
  id TEXT PRIMARY KEY,
  source_message_id TEXT NOT NULL REFERENCES mail_source_messages(id),
  run_number INTEGER NOT NULL,
  status TEXT NOT NULL CHECK(status IN (
    'PROCESSING','RETRY_WAIT','REVIEW_REQUIRED','NON_ACTIONABLE','COMPLETED','FAILED_PERMANENT'
  )),
  normalization_version TEXT NOT NULL,
  normalized_output_json TEXT,
  deterministic_evidence_json TEXT,
  ai_structured_output_json TEXT,
  validation_result_json TEXT,
  model_name TEXT,
  model_snapshot TEXT,
  prompt_version TEXT,
  schema_version TEXT,
  source_content_sha256 TEXT,
  model_input_sha256 TEXT,
  model_output_sha256 TEXT,
  latency_ms INTEGER,
  input_tokens INTEGER,
  output_tokens INTEGER,
  total_tokens INTEGER,
  disagreement_flags_json TEXT NOT NULL DEFAULT '[]',
  error_code TEXT,
  started_at TEXT NOT NULL,
  completed_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(source_message_id,run_number)
);
CREATE TABLE canonical_mail_events (
  id TEXT PRIMARY KEY,
  source_message_id TEXT NOT NULL REFERENCES mail_source_messages(id),
  processing_run_id TEXT REFERENCES mail_processing_runs(id),
  complaint_id TEXT REFERENCES complaints(id),
  event_version TEXT NOT NULL,
  event_type TEXT NOT NULL CHECK(event_type IN (
    'NEW_CASE','FOLLOW_UP','CASE_UPDATE','RESPONSE_REQUEST','DUPLICATE_SOURCE','NON_ACTIONABLE','REVIEW_REQUIRED'
  )),
  external_case_id TEXT,
  canonical_store_number TEXT,
  ingestion_mode TEXT NOT NULL CHECK(ingestion_mode IN ('LIVE','BACKFILL','TEST')),
  payload_json TEXT NOT NULL,
  occurred_at TEXT,
  validated_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  UNIQUE(source_message_id,event_version)
);
CREATE TABLE complaint_sources (
  id TEXT PRIMARY KEY,
  complaint_id TEXT NOT NULL REFERENCES complaints(id),
  source_message_id TEXT NOT NULL UNIQUE REFERENCES mail_source_messages(id),
  canonical_mail_event_id TEXT REFERENCES canonical_mail_events(id),
  source_role TEXT NOT NULL CHECK(source_role IN (
    'INITIAL','FOLLOW_UP','CASE_UPDATE','DUPLICATE','RESPONSE_REQUEST'
  )),
  linkage_basis TEXT NOT NULL,
  material_update INTEGER NOT NULL DEFAULT 0,
  linked_at TEXT NOT NULL
);
CREATE TABLE mail_review_items (
  id TEXT PRIMARY KEY,
  source_message_id TEXT NOT NULL REFERENCES mail_source_messages(id),
  processing_run_id TEXT REFERENCES mail_processing_runs(id),
  canonical_mail_event_id TEXT REFERENCES canonical_mail_events(id),
  complaint_id TEXT REFERENCES complaints(id),
  status TEXT NOT NULL CHECK(status IN ('OPEN','RESOLVED','DISMISSED')),
  reason_code TEXT NOT NULL,
  disagreement_flags_json TEXT NOT NULL DEFAULT '[]',
  resolution_json TEXT,
  reviewed_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL,
  resolved_at TEXT,
  updated_at TEXT NOT NULL
);
CREATE TABLE response_actions (
  id TEXT PRIMARY KEY,
  complaint_id TEXT NOT NULL REFERENCES complaints(id),
  source_message_id TEXT REFERENCES mail_source_messages(id),
  response_kind TEXT NOT NULL CHECK(response_kind IN ('RECEIPT_ACK','SUBSTANTIVE_RESPONSE')),
  policy_version TEXT NOT NULL,
  policy_state TEXT NOT NULL CHECK(policy_state IN (
    'NOT_EVALUATED','NO_RESPONSE','ACK_ELIGIBLE','ACK_ALREADY_SENT','ACK_BLOCKED',
    'DRAFT_REQUIRED','OWNER_APPROVAL_REQUIRED','READY_TO_SEND','SENT'
  )),
  content_kind TEXT CHECK(content_kind IN ('DETERMINISTIC_TEMPLATE','AI_DRAFT','HUMAN_EDITED')),
  content_ref TEXT,
  template_version TEXT,
  model_name TEXT,
  model_snapshot TEXT,
  prompt_version TEXT,
  approved_by TEXT REFERENCES users(id),
  approved_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(complaint_id,response_kind,policy_version)
);
CREATE TABLE outbound_deliveries (
  id TEXT PRIMARY KEY,
  response_action_id TEXT REFERENCES response_actions(id),
  notification_id TEXT REFERENCES notifications(id),
  channel TEXT NOT NULL CHECK(channel IN ('EMAIL','SMS')),
  provider TEXT NOT NULL,
  idempotency_key TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL CHECK(status IN (
    'PENDING','PROCESSING','SENT','DELIVERED','FAILED_RETRYABLE','FAILED_PERMANENT','SEND_UNKNOWN','SUPPRESSED'
  )),
  provider_message_id TEXT,
  attempt_count INTEGER NOT NULL DEFAULT 0,
  lease_owner TEXT,
  lease_expires_at TEXT,
  last_error_code TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  sent_at TEXT,
  delivered_at TEXT,
  CHECK(response_action_id IS NOT NULL OR notification_id IS NOT NULL)
);
CREATE TABLE push_subscriptions (
  id TEXT PRIMARY KEY,
  organization_id TEXT NOT NULL REFERENCES organizations(id),
  user_id TEXT NOT NULL REFERENCES users(id),
  endpoint TEXT NOT NULL UNIQUE,
  p256dh_key TEXT NOT NULL,
  auth_key TEXT NOT NULL,
  device_label TEXT,
  created_at TEXT NOT NULL,
  last_used_at TEXT,
  revoked_at TEXT
);
DELETE FROM sqlite_sequence;
CREATE INDEX complaint_store_idx ON complaints(store_id);
CREATE INDEX complaint_status_idx ON complaints(status);
CREATE INDEX event_complaint_idx ON complaint_events(complaint_id);
CREATE INDEX notification_complaint_idx ON notifications(complaint_id);
CREATE UNIQUE INDEX notification_provider_message_idx ON notifications(provider_message_id) WHERE provider_message_id IS NOT NULL;
CREATE UNIQUE INDEX complaint_gmail_message_idx ON complaints(gmail_message_id) WHERE gmail_message_id IS NOT NULL;
CREATE INDEX complaint_gmail_thread_idx ON complaints(gmail_thread_id) WHERE gmail_thread_id IS NOT NULL;
CREATE INDEX gmail_thread_idx ON gmail_messages(gmail_thread_id);
CREATE INDEX gmail_processing_idx ON gmail_messages(processing_status,internal_date);
CREATE INDEX integration_event_recent_idx ON integration_events(created_at DESC);
CREATE INDEX background_job_recent_idx ON background_job_runs(job_name,started_at DESC);
CREATE INDEX mail_source_processing_idx
  ON mail_source_messages(processing_state,lease_expires_at,received_at);
CREATE INDEX mail_source_conversation_idx
  ON mail_source_messages(provider,mailbox_key,conversation_id);
CREATE INDEX mail_processing_source_idx
  ON mail_processing_runs(source_message_id,run_number DESC);
CREATE INDEX canonical_mail_case_idx ON canonical_mail_events(external_case_id,created_at);
CREATE INDEX complaint_sources_complaint_idx ON complaint_sources(complaint_id,linked_at);
CREATE INDEX mail_review_open_idx ON mail_review_items(status,created_at);
CREATE INDEX outbound_delivery_work_idx
  ON outbound_deliveries(status,lease_expires_at,created_at);
CREATE INDEX idx_push_subscriptions_user ON push_subscriptions(user_id);
